import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p33_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor batchnorm2d_infer_cuda(
    torch::Tensor x,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("batchnorm2d_infer_cuda", &batchnorm2d_infer_cuda, "BatchNorm2d inference (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256

__global__ void batchnorm2d_infer_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float eps,
    int N, int C, int HW
) {
    int c = blockIdx.x;
    if (c >= C) return;

    float mean = running_mean[c];
    float var  = running_var[c];
    float w    = weight[c];
    float b    = bias[c];
    float scale = w * rsqrtf(var + eps);
    float shift = b - mean * scale;

    long long spatial_total = (long long)N * HW;
    long long base = (long long)c * spatial_total;

    for (long long idx = blockIdx.y * BLOCK_SIZE + threadIdx.x;
         idx < spatial_total;
         idx += (long long)gridDim.y * BLOCK_SIZE) {
        // NCHW: element at (n, c, hw) = n*C*HW + c*HW + hw
        // We iterate over all (n, hw) pairs for this channel
        int n   = (int)(idx / HW);
        int hw  = (int)(idx % HW);
        long long in_idx = (long long)n * C * HW + (long long)c * HW + hw;
        y[in_idx] = x[in_idx] * scale + shift;
    }
}

__global__ void batchnorm2d_infer_kernel_vec4(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float eps,
    int N, int C, int HW
) {
    int c = blockIdx.x;
    if (c >= C) return;

    float mean = running_mean[c];
    float var  = running_var[c];
    float w    = weight[c];
    float b    = bias[c];
    float scale = w * rsqrtf(var + eps);
    float shift = b - mean * scale;

    long long spatial_total = (long long)N * HW;
    long long vec_total = spatial_total / 4;

    const float4* x4 = reinterpret_cast<const float4*>(x + (long long)c * spatial_total);
    float4* y4 = reinterpret_cast<float4*>(y + (long long)c * spatial_total);

    for (long long idx = blockIdx.y * BLOCK_SIZE + threadIdx.x;
         idx < vec_total;
         idx += (long long)gridDim.y * BLOCK_SIZE) {
        float4 v = x4[idx];
        v.x = v.x * scale + shift;
        v.y = v.y * scale + shift;
        v.z = v.z * scale + shift;
        v.w = v.w * scale + shift;
        y4[idx] = v;
    }
    // tail
    long long tail_start = vec_total * 4;
    for (long long idx = tail_start + blockIdx.y * BLOCK_SIZE + threadIdx.x;
         idx < spatial_total;
         idx += (long long)gridDim.y * BLOCK_SIZE) {
        long long in_idx = (long long)c * spatial_total + idx;
        y[in_idx] = x[in_idx] * scale + shift;
    }
}

torch::Tensor batchnorm2d_infer_cuda(
    torch::Tensor x,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps
) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be 4D");

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int HW = H * W;

    auto y = torch::empty_like(x);

    long long spatial_total = (long long)N * HW;
    bool use_vec4 = (spatial_total % 4 == 0) &&
                    ((reinterpret_cast<uintptr_t>(x.data_ptr<float>()) % 16) == 0);

    // Choose gridDim.y to cover spatial_total
    int grid_y = (int)((spatial_total + (long long)BLOCK_SIZE - 1) / BLOCK_SIZE);
    // Cap to avoid too many blocks
    if (grid_y > 4096) grid_y = 4096;

    dim3 grid(C, grid_y);
    dim3 block(BLOCK_SIZE);

    if (use_vec4) {
        batchnorm2d_infer_kernel_vec4<<<grid, block>>>(
            x.data_ptr<float>(), y.data_ptr<float>(),
            running_mean.data_ptr<float>(), running_var.data_ptr<float>(),
            weight.data_ptr<float>(), bias.data_ptr<float>(),
            (float)eps, N, C, HW
        );
    } else {
        batchnorm2d_infer_kernel<<<grid, block>>>(
            x.data_ptr<float>(), y.data_ptr<float>(),
            running_mean.data_ptr<float>(), running_var.data_ptr<float>(),
            weight.data_ptr<float>(), bias.data_ptr<float>(),
            (float)eps, N, C, HW
        );
    }

    return y;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs Batch Normalization.
        """
    def __init__(self, num_features: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the BatchNorm layer.

                Args:
                    num_features (int): Number of features in the input tensor.
                """
        self.bn = nn.BatchNorm2d(num_features=num_features)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        if (
            not self.training and
            x.is_cuda and
            x.dtype == torch.float32 and
            x.dim() == 4 and
            x.is_contiguous() and
            self.bn.weight is not None and
            self.bn.bias is not None and
            self.bn.running_mean is not None and
            self.bn.running_var is not None and
            self.bn.running_mean.is_cuda and
            self.bn.weight.is_contiguous() and
            self.bn.bias.is_contiguous() and
            self.bn.running_mean.is_contiguous() and
            self.bn.running_var.is_contiguous()
        ):
            return _stark_get_extension().batchnorm2d_infer_cuda(
                x,
                self.bn.running_mean,
                self.bn.running_var,
                self.bn.weight,
                self.bn.bias,
                float(self.bn.eps)
            )
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return self.bn(x)
        # <<<END_IMPROVE>>>

