#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Vectorized kernel: each thread processes 4 floats along the spatial dimension
// Grid: (C, ceil(N*H*W/4 / BLOCK_SIZE))
// Each block handles one channel c and a tile of spatial elements
#define BLOCK_SIZE 256

__global__ void batchnorm2d_infer_kernel_vec4(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ scale,  // precomputed weight * rsqrt(var+eps)
    const float* __restrict__ shift,  // precomputed bias - mean*scale
    int C, int HW, long long spatial_total
) {
    int c = blockIdx.x;
    if (c >= C) return;

    float sc = scale[c];
    float sh = shift[c];

    // Each thread handles 4 consecutive spatial elements
    long long base4 = (long long)blockIdx.y * BLOCK_SIZE + threadIdx.x;
    long long stride4 = (long long)gridDim.y * BLOCK_SIZE;

    // For NCHW layout, elements for channel c are at positions:
    // n*C*HW + c*HW + hw  for hw in [0, HW)
    // We iterate over all (n, hw) pairs for this channel
    // spatial_total = N * HW
    // We process 4 elements at a time
    long long spatial4 = spatial_total / 4;

    for (long long i = base4; i < spatial4; i += stride4) {
        long long idx4 = i * 4;
        // Compute NCHW indices for 4 consecutive spatial positions
        // idx4 is the flat index into the (N*HW) space for channel c
        // n = idx4 / HW, hw = idx4 % HW
        // But since we need contiguous memory access, we need to check if
        // these 4 elements are contiguous in memory.
        // In NCHW: element (n, c, hw) is at n*C*HW + c*HW + hw
        // For fixed c, consecutive hw values within same n are contiguous.
        // But crossing n boundary: n*C*HW + c*HW + HW vs (n+1)*C*HW + c*HW + 0
        // These are NOT contiguous (gap of (C-1)*HW).
        // So we can only vectorize within a row (same n).
        // For simplicity, use scalar loads but process 4 iterations unrolled.
        long long n0 = idx4 / HW;
        long long hw0 = idx4 % HW;
        long long in0 = n0 * (long long)C * HW + (long long)c * HW + hw0;

        // Check if all 4 are in the same row (same n)
        if (hw0 + 3 < HW) {
            // All 4 in same row - can use float4 load
            float4 xv = *reinterpret_cast<const float4*>(x + in0);
            float4 yv;
            yv.x = xv.x * sc + sh;
            yv.y = xv.y * sc + sh;
            yv.z = xv.z * sc + sh;
            yv.w = xv.w * sc + sh;
            *reinterpret_cast<float4*>(y + in0) = yv;
        } else {
            // Crosses row boundary - scalar fallback
            for (int k = 0; k < 4; k++) {
                long long idx = idx4 + k;
                long long n = idx / HW;
                long long hw = idx % HW;
                long long in_idx = n * (long long)C * HW + (long long)c * HW + hw;
                y[in_idx] = x[in_idx] * sc + sh;
            }
        }
    }

    // Handle tail elements
    long long tail_start = spatial4 * 4;
    for (long long idx = tail_start + (long long)blockIdx.y * BLOCK_SIZE + threadIdx.x;
         idx < spatial_total;
         idx += (long long)gridDim.y * BLOCK_SIZE) {
        long long n = idx / HW;
        long long hw = idx % HW;
        long long in_idx = n * (long long)C * HW + (long long)c * HW + hw;
        y[in_idx] = x[in_idx] * sc + sh;
    }
}

// Scalar kernel for fallback
__global__ void batchnorm2d_infer_kernel_scalar(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ scale,
    const float* __restrict__ shift,
    int C, int HW, long long spatial_total
) {
    int c = blockIdx.x;
    if (c >= C) return;

    float sc = scale[c];
    float sh = shift[c];

    for (long long idx = (long long)blockIdx.y * BLOCK_SIZE + threadIdx.x;
         idx < spatial_total;
         idx += (long long)gridDim.y * BLOCK_SIZE) {
        long long n = idx / HW;
        long long hw = idx % HW;
        long long in_idx = n * (long long)C * HW + (long long)c * HW + hw;
        y[in_idx] = x[in_idx] * sc + sh;
    }
}

torch::Tensor batchnorm2d_infer_cuda(
    torch::Tensor x,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps
) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be 4D");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int HW = H * W;
    long long spatial_total = (long long)N * HW;

    // Precompute scale and shift on GPU
    // scale[c] = weight[c] * rsqrt(running_var[c] + eps)
    // shift[c] = bias[c] - running_mean[c] * scale[c]
    auto scale_t = weight * (running_var + (float)eps).rsqrt();
    auto shift_t = bias - running_mean * scale_t;

    auto y = torch::empty_like(x);

    const float* x_ptr = x.data_ptr<float>();
    float* y_ptr = y.data_ptr<float>();
    const float* scale_ptr = scale_t.data_ptr<float>();
    const float* shift_ptr = shift_t.data_ptr<float>();

